func (q *Queries) ListServiceTasks(ctx context.Context, serviceID uuid.UUID) ([]ServiceTask, error) {
	rows, err := q.db.Query(ctx, listServiceTasks, serviceID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ServiceTask{}
	for rows.Next() {
		var i ServiceTask
		if err := rows.Scan(
			&i.ID,
			&i.ServiceID,
			&i.Name,
			&i.Schedule,
			&i.Command,
			&i.Enabled,
			&i.TimeoutSeconds,
			&i.Concurrency,
			&i.NextRunAt,
			&i.LastRunAt,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.Timezone,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listTaskRunLogs = `-- name: ListTaskRunLogs :many
SELECT id, stream, line, created_at FROM task_run_logs
WHERE run_id = $1 AND id > $2
ORDER BY id
LIMIT $3
`

type ListTaskRunLogsParams struct {
	RunID uuid.UUID `json:"runId"`
	ID    int64     `json:"id"`
	Limit int32     `json:"limit"`
}

type ListTaskRunLogsRow struct {
	ID        int64     `json:"id"`
	Stream    string    `json:"stream"`
	Line      string    `json:"line"`
	CreatedAt time.Time `json:"createdAt"`
}

func (q *Queries) ListTaskRunLogs(ctx context.Context, arg ListTaskRunLogsParams) ([]ListTaskRunLogsRow, error) {
	rows, err := q.db.Query(ctx, listTaskRunLogs, arg.RunID, arg.ID, arg.Limit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListTaskRunLogsRow{}
	for rows.Next() {
		var i ListTaskRunLogsRow
		if err := rows.Scan(
			&i.ID,
			&i.Stream,
			&i.Line,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const pruneTaskRuns = `-- name: PruneTaskRuns :execrows
DELETE FROM task_runs
WHERE id IN (
    SELECT t.id FROM task_runs t
    WHERE t.service_id = $1
      AND t.task_id IS NOT DISTINCT FROM $2::uuid
      AND t.status NOT IN ('queued','running')
    ORDER BY t.created_at DESC, t.id DESC
    OFFSET $3
)
`

type PruneTaskRunsParams struct {
	ServiceID uuid.UUID  `json:"serviceId"`
	TaskID    *uuid.UUID `json:"taskId"`
	Keep      int32      `json:"keep"`
}

// Keeps the newest row_limit finished runs of one task (or, with a null
// task_id, of the service's one-off runs); active runs are never removed.
func (q *Queries) PruneTaskRuns(ctx context.Context, arg PruneTaskRunsParams) (int64, error) {
	result, err := q.db.Exec(ctx, pruneTaskRuns, arg.ServiceID, arg.TaskID, arg.Keep)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

