const updateServiceTask = `-- name: UpdateServiceTask :one
UPDATE service_tasks SET
    name = $1,
    schedule = $2,
    timezone = $3,
    command = $4,
    enabled = $5,
    timeout_seconds = $6,
    concurrency = $7,
    next_run_at = $8,
    updated_at = now()
WHERE id = $9
RETURNING id, service_id, name, schedule, command, enabled, timeout_seconds, concurrency, next_run_at, last_run_at, created_at, updated_at, timezone
`

type UpdateServiceTaskParams struct {
	Name           string          `json:"name"`
	Schedule       string          `json:"schedule"`
	Timezone       string          `json:"timezone"`
	Command        json.RawMessage `json:"command"`
	Enabled        bool            `json:"enabled"`
	TimeoutSeconds int32           `json:"timeoutSeconds"`
	Concurrency    string          `json:"concurrency"`
	NextRunAt      *time.Time      `json:"nextRunAt"`
	ID             uuid.UUID       `json:"id"`
}

func (q *Queries) UpdateServiceTask(ctx context.Context, arg UpdateServiceTaskParams) (ServiceTask, error) {
	row := q.db.QueryRow(ctx, updateServiceTask,
		arg.Name,
		arg.Schedule,
		arg.Timezone,
		arg.Command,
		arg.Enabled,
		arg.TimeoutSeconds,
		arg.Concurrency,
		arg.NextRunAt,
		arg.ID,
	)
	var i ServiceTask
	err := row.Scan(
		&i.ID,
		&i.ServiceID,
		&i.Name,
		&i.Schedule,
		&i.Command,
		&i.Enabled,
		&i.TimeoutSeconds,
		&i.Concurrency,
		&i.NextRunAt,
		&i.LastRunAt,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.Timezone,
	)
	return i, err
}
